quests[79097] = { id = 79097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baxtan: On Destructive Magics", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79098] = { id = 79098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Forest!", description = "This one is slain, but these infuriating alliance continue to fight... what is this charm?", sourceObjective = "Bring the Silverwing Sentinel Charm to Kazragore, Far Seer, at the Bonfire base in Ashenvale.", progress = "{name}, what news do you have from the front?", completion = "These Alliance dogs still prevent us from harvesting the resources needed for Orgrimmar. Continue to drive them out!\n\nThis Warsong battle drum will inspire you to fight them with greater determination. Lok'tar Ogar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[79099] = { id = 79099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "Greetings {class}. I've heard the most curious stories from the locals of a great corrupted water elemental named Baron Aquanis that stands vigil near the entrance to the Night Elf ruins known as Blackfathom Deeps. I'm here looking to hire adventurers brave enough to retrieve the core of Baron Aquanis, a globe of corrupted water. In exchange, I'd be willing to give you access to a portal directly to the Zoram Strand that I've been using to study the environs around the ruins... from a safe distance, of course.", sourceObjective = "Bring the Strange Water Globe to Davidus Voidstar in Auberdine, Darkshore.", progress = "Ah, hello again {name}. Have you retrieved the globe?", completion = "Hmm, most curious. This... isn't what I expected. Very well, thank you for this. As promised, you may now utilize my portal to the Zoram Strand.", sourceObjectiveStatus = "unverified-source-field" }
quests[79100] = { id = 79100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Waylaid Shipment", sourceObjective = "The shipment's missing some items, but it will still be of some use.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79101] = { id = 79101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[79102] = { id = 79102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[79103] = { id = 79103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[79192] = { id = 79192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stepping Stones", description = "The note begins, \"Mission said they were both making deliveries for New Plague. Looks like simple apothecary accidents to me. Find my cozy spot in the mountains between The Barrens and Desolace if you want a safe place to talk.\"", sourceObjective = "You tear the note from the plank and read the scrawled writing.", completion = "Backcountry adventurers and mercenaries alike undoubtedly make camp here. The corner of a note flapping in the breeze catches your eye and you reach for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[79229] = { id = 79229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highway Robbery", description = "The campsite before you is a grisly scene. Judging by the remains, the victims were two humans and a dwarf. Markings on the bones indicate a savage attack, but the looted supplies tell you this wasn't done by an animal. The wounds don't match centaur weaponry either.\n\nPerhaps an experienced scavenger of these lands would know what to make of this.", sourceObjective = "Find someone in Desolace who knows about the pillaged campsite.", completion = "Ah, so you found another one...", sourceObjectiveStatus = "unverified-source-field" }
quests[79235] = { id = 79235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Lam", description = "I've found a couple of scenes like you describe, {name}. Always camps of humans and dwarves. Rumor among the caravans is a group of Horde marauders did it. Seems likely given the victims, and how brutal the attacks were.\n\nApparently the bandits fled Desolace once an Alliance marshal got hot on their trail.\n\nIf you're looking to track one of 'em down, I'd check in a port town. Those always have shady characters coming and going. Might catch one trying to get a boat to somewhere.", sourceObjective = "Find one of the Desolace marauders.", completion = "You need something? Make it quick.", sourceObjectiveStatus = "unverified-source-field" }
quests[79236] = { id = 79236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cherry for Your Thoughts?", description = "You with the marshal? No, you don't look like it.\n\nThe rumors you've heard are only half true. Yes, we were pillaging human and dwarven camps, but we weren't doing it for the Horde. We were privately employed.\n\nI'll tell ya the whole story if you buy me some grog.", sourceObjective = "Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story.", progress = "How's that drink coming?", completion = "Ah, that's the stuff. Now, where was I?", sourceObjectiveStatus = "unverified-source-field" }
quests[79242] = { id = 79242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Honor Among Thieves", description = "As I was saying...\n\nOur boss wasn't with the Horde. She was a night elf named Illari Duskfeather. She gave us intel on the camps, and even let us keep most of the loot. She only kept a few of the rarer finds.\n\nOnce the Marshal was on our tail, though, she left us for dead. I don't know her motives, but I think we were set up as patsies.\n\nI'm not the vengeful type, but I won't stop someone else from hunting her down. If you're looking for her, she once mentioned a hideout somewhere near Arathi.", sourceObjective = "Find Illari Duskfeather, near Arathi Highlands, and get access to her cache of stolen loot.", progress = "<Using Illari's key, you unlock the cache.>", completion = "<Inside of the cache, you find a small box, along with some coin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79298] = { id = 79298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempting Fate", description = "You can see foul magic is poisoning the water, giving it a purple hue. The Burning Blade have overwhelmed this area with dark energy.\n\nWe shall use this Sacrificial Alter that they use during summoning rituals. We can harness the latent dark energy in the area to amplify our ritual.", sourceObjective = "Assist Raszel Ander and Doan Karhan with the summoning ritual and trap Des'Altek inside the staff.", completion = "For all things Raszel Ander was, commanding was not one of the traits I knew. For a {class}, he was always on the meek side. I had a feeling something wasn't right when that imposter returned during your summoning ritual, which was why I sent for more acolytes to assist, but it wasn't enough... Once again we have failed to ensnare our prey.\n\nUnfortunately, the staff shattered during your fight, and all I could do was stand by helpless and watch... but I found this in the destruction.", sourceObjectiveStatus = "unverified-source-field" }
quests[79348] = { id = 79348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Ancient", description = "A putrid seed is all that remains of the wandering ancient. Its outer coat is brittle, and the insides emit a foul odor.\n\nGiven its size, the ancient this seed came from must have been fairly young; at least by ancient standards. One has to wonder why such a creature would be found trudging through The Quagmire.  \n\nTo find your answers, you should take this seed to someone with knowledge in the lore of ancients.", sourceObjective = "Find someone who can tell you more about the rotten ancient seed.", completion = "Ah, another lost youngling...", sourceObjectiveStatus = "unverified-source-field" }
quests[79358] = { id = 79358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tattered Note", description = "<You unfold a torn piece of parchment that reads:>\n\nThe tunnels have reached the bluffs above Thousand Needles and our preparations have gone unseen, but we must act swiftly. Send your shaman; with all that Hirzek has accomplished we are ready to begin.\n\nThe storm will rage, the ground will rumble and the tide shall rise, leaving only carcasses to animate in our wake. Their bones will blaze a trail into...\n\n<The note ends abruptly at the bottom of the torn page.>", sourceObjective = "Warn the denizens of Thousand Needles of what you have discovered.", completion = "<Hmmph... the large tauren snorts as he reads the parchment.>\n\nOne things certain... whoever this note is from is right about their preparations going unseen. We've been too busy dealing with the centaur and harpies to send out wind riders to patrol the canyon and bluffs.\n\nYou have our gratitude for alerting us to this threat, but we might still need further assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[79360] = { id = 79360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Aid", description = "I've heard of Hirzek, and the barbaric lengths they have gone to manipulate the elements.\n\n<Rau's eyes wander as he ponders the note, speaking to himself aloud.>\n\nThe storm will rage, the ground will rumble, and the tide will rise...\n\n<Rau's eyes focus you and widen as he comes to the realization.>\n\nThey must be using some cruel sorcery they learned from Hirzek. They plan to flood the canyon and raise us all into undeath.\n\nTo achieve their goal, I fear they require devastating elemental powers.", sourceObjective = "While many inhabitants of Thousand Needles are our enemies, we can't stand by and watch them get washed away. The note was clear, they plan to raise an undead army in the aftermath, which potentially threatens us all.\n\nWe are ill equipped to deal with this, but I've heard of a shaman on the Eastern Kingdoms who's proficient in the elemental imbuement of weapons, they might be capable of helping.\n\nFind this shaman and plead for their aid.", completion = "<You hand the note to Bath'rah who reads it over and gives a half hearted chuckle.>\n\nAh so it be true mon... I too have sensed much unrest in the elemental plane and dis must be one of the causes.\n\nTo flood all da Thousand Needles would take a great storm and many lives be lost.\n\nI t'ink I got just da t'ing for ya, but it won't come easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[79361] = { id = 79361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of da Wind", description = "A violent storm of this size will require the power of da wind to spread across the land. Whatever this ritual be, we must protect you against dis element.\n\nDe whirlwind elementals have ravaged Desolace and are one of the only remaining elements capable of inhabiting the land. Bring me their essence.", sourceObjective = "Collect 5 Whirling Essence from the whirlwind elementals in Desolace and bring them to Bath'rah the Windwatcher in Alterac Mountains.", progress = "Ah, you be gettin' a bit dusty out der?", completion = "Oh yes, yes. We be cookin' now.", sourceObjectiveStatus = "unverified-source-field" }
quests[79362] = { id = 79362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of da Earth", description = "Ta make the ground rumble will require a strong connection to de earth. De Badlands be filt wit stones and boulders hardened by time. De embodiments of earth roam these lands and call it home.", sourceObjective = "Collect 5 Rumbling Essence from the rock elementals in Badlands and bring them to Bath'rah the Windwatcher in Alterac Mountains.", progress = "You' legs be lookin' a wobbly der. De ground be shakin?", completion = "Let's get ready to rumble, ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[79363] = { id = 79363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of da Water", description = "Now dat flood be the worst part, mon. Dat canyon be dry and water flow for days on dat hard cracked ground and the basin be gone in a flash.\n\nNot many elementals, dat I know of,  be containing that type of power, but...\n\n<Bath'rah looks at you with a sly grin.>\n\nYou know I gotch'ya back broda.\n\nThe mires of Dustwallow Marsh is where you should go. While not purely water elementals, dose withering got secrets.", sourceObjective = "Collect 5 Rushing Essence from the withering elementals in Dustwallow Marsh and bring them to Bath'rah the Windwatcher in Alterac Mountains.", progress = "Wade into any danger yet?", completion = "Shake dat sludge off, we almost done.", sourceObjectiveStatus = "unverified-source-field" }
quests[79364] = { id = 79364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Container", description = "You've done well mon. While I don't know what you be facin' out there in da Thousand Needles this will surely provide you some protection against the elements dat threaten der land.\n\n<Bath'rah begins to shuffle through his belongings, and you can see him get a little frustrated as he searches quicker and quicker before looking up at you sheepishly.>\n\nWell there be one more t'ing I need from you.\n\n<His grin widens before he speaks again.>\n\nI seem to have misplace me potion vials...", sourceObjective = "You didn't think I'd be making some crazy weapon for ya did you's? Nah, nah, nah me friend dis be a potion of protection.\n\nFightin' fire with fire not always be the right approach mon.\n\nBring a Crystal Vial to Bath'rah the Windwatcher in Alterac Mountains.", progress = "We need a larger vial and one of crystal clarity to contain these elements.", completion = "Knew I could count on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[79365] = { id = 79365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Wind Beneath Your Wings", description = "Here mon, a Squall-breakers Potion be what you need. Drink this to protect yourself against the elements of the storm, but remember it only goin' to last for a short while.\n\nNow go, return to your friends in need. There's nothing more I can do for you.", sourceObjective = "Return to Rau Cliffrunner in Thousand Needles at Freewind Post.\n\nProvided item:", completion = "Our wind riders have found something, but they have been unable to get close enough to assess the situation. Were you able to find anything that might help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[79366] = { id = 79366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calm Before the Storm", description = "We found an unusual amount of storm activity isolated in the bluffs to the northeast near Razorfen territory.\n\nThe wind was too powerful for the riders to get close and the density of the rain made it impossible to see what's waiting for you inside the eye. But maybe with that potion you can break on through to the other side.\n\nSpeak with Nyse, Wind Rider Master, when you are ready. She will provide a wyvern to ride into the storm.", sourceObjective = "Venture into the eye of the storm and confront the quilboars.", progress = "What did you find?", completion = "The rumbling ground fell silent and in my heart I knew you had saved us. You have our gratitude, {name}.\n\nPlease accept one of these gifts as a token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[79377] = { id = 79377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Saplings", description = "In times of unrest, seeds may take root in bitter soil. Ancients born this way are prone to corruption. They wander hostile lands; never finding peace.\n\nI have sensed four saplings who may be spared such a fate. They are lost among the Eastern Kingdoms, with leaves like that of each season.\n\nPlease, take this water to them, so that they may be healed.\n\nBe warned, the water's magic is delicate. Teleportation will destroy it. Its potency will also fade over time.", sourceObjective = "Find the four lost saplings in Eastern Kingdoms, and share the Water of Elune'ara with them. Afterwards, return to Orokai, in Moonglade.", progress = "Make haste, {name}. My kin may yet be saved.", completion = "Your deeds have preserved centuries of life, {name}. I am immensely grateful. May you bring yet more healing upon this land in the times to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[79442] = { id = 79442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching Up", description = "Our people cannot thank you enough, but I have no real use for this eye. Maybe that ol' Windwatcher could put it to good use?", sourceObjective = "Return to Bath'rah the Windwatcher in Alterac Mountains and see if he can put the Eye of the Tempest to use.", progress = "Ahh! Looks like ye made it back in one piece there. Now tell me how did de potion do?\n\nWell 'tis a good thing I had faith in ya. Cuz dat potion be nothing but a mighty fine punch bru'dah. Much tastier than it be effective against those storms.\n\nNow, now... don't be angry wit me. All ya needed was a little encouragement. T'ings turned out how they was always meant to.\n\nBut since you's here... I did notice that mighty fine eye you be holdin...", completion = "Tell ya what. No more tricks, no more games. I got somet'in you'd be interested in.\n\nTrade me dat eye and I give you here this mighty fine rune that be ready to teach you new tricks.\n\nWhat ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[79482] = { id = 79482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", sourceObjective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", sourceObjectiveStatus = "unverified-source-field" }
quests[79483] = { id = 79483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", sourceObjective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", sourceObjectiveStatus = "unverified-source-field" }
quests[79484] = { id = 79484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're a Mean One...", description = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, {name}.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats {name}, take them b-b-back to Smokywood Pastures in Ironforge, and t-t-tell them I n-n-need to be unfrozen!", sourceObjective = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.", progress = "{name} - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[79485] = { id = 79485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're a Mean One...", description = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, {name}.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats {name}, take them b-b-back to Smokywood Pastures in Orgrimmar, and t-t-tell them I n-n-need to be unfrozen!", sourceObjective = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.", progress = "{name} - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", sourceObjectiveStatus = "unverified-source-field" }
quests[79486] = { id = 79486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", sourceObjective = "Speak with Greatfather Winter in Ironforge.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[79487] = { id = 79487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", sourceObjective = "Speak with Great-father Winter in Orgrimmar.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[79492] = { id = 79492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Greatfather Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", sourceObjective = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed.", progress = "{name}!  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Greatfather Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[79495] = { id = 79495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", sourceObjective = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.", progress = "{name}!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[79501] = { id = 79501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", sourceObjective = "Bring 1 Deeprock Salt and 5 gold coins to any Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!", sourceObjectiveStatus = "unverified-source-field" }
quests[79502] = { id = 79502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", sourceObjective = "Bring 1 Deeprock Salt and 5 gold coins to the Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!", sourceObjectiveStatus = "unverified-source-field" }
quests[79535] = { id = 79535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisks: Should Petrification be Feared?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79536] = { id = 79536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Friend of the Library", sourceObjective = "Thanks to your donations, the library is thriving.\n\nPlease, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[79588] = { id = 79588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Furry Paws", progress = "The first lesson in drawing a crowd is: lure them with gadgets and trinkets!  Can you help me?\n\nI need small furry paws to use for prizes.  You can find those on the cats of the Barrens or Darkshore....\n\nBring me some paws and I'll trade you a Darkmoon Faire ticket for them.", completion = "Great, you got them!  We can use these to make toys and baubles, and those will attract more people to the Faire!\n\nHere's your ticket, {name}.  You earned it!" }
quests[79589] = { id = 79589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Bear Pelts", progress = "Children love toys!  And no matter what race, I've found that all children love furry, plushy toys made from torn bear pelts!\n\nYou can get those pelts from the bears of Ashenvale or Hillsbrad.  Bring me a heap of them and earn yourself a heap of Darkmoon Faire tickets!", completion = "Nice pelts, {name}!  I'll get someone to sew these into a bunch of plush toys.  With a little stuffing and some paint, I think they'll be the envy of children across Azeroth!\n\nTickets?  Ah yes, your payment!  Here they are!" }
quests[79590] = { id = 79590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Grinding Stone", progress = "To help with my workout, I like to fit a staff between heavy grinding stones, then lift the staff over my head.  It isn't easy, but being the strongest woman in the world, like I am, can't be earned sitting down!\n\nCan you help me?  I need more grinding stones - bring me some and I'll trade Darkmoon Faire tickets for them.", completion = "You brought the stones!  And they're heavy!  I can already feel my muscles getting bigger.  Thanks {name}!\n\nHere, take these tickets, and be sure not to eat too many sweets while you're at the faire.  A big strong {class} like you needs to keep himself in fighting shape!" }
quests[79591] = { id = 79591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whirring Bronze Gizmo", progress = "My new booth will be a sight to see, yes sir!  A sight to see, and... for a lucky few, to touch!\n\nI can already hear the whirring bronze gizmos singing their song of mechanical rapture as patrons step to my booth and test their skill!\n\nAh... now I need the gizmos themselves to bring my dream closer to fruition.  Please, {name}, bring me whirring bronze gizmos... and Darkmoon Faire tickets will be yours!", completion = "You brought the gizmos!  Wonderful!  Even now I can hear their buzzing, whirring chorus in my mind!  Oh, when this booth is ready it will be the wonder of the world, mark me!\n\nHere are you tickets, {name}.  And please enjoy your stay at the Faire!" }
quests[79592] = { id = 79592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carnival Jerkins", progress = "Our Faire workers do more than sweep trash and hammer spikes!  They also help guard the carnival as it travels, and to that end they are always needing good sturdy armor jerkins.\n\nIf you make some tough leather armor and bring it to me, then I'll make sure it gets to the right people.  I'll also get you some Darkmoon Faire tickets as trade.", completion = "Ah, you brought the jerkins.  Splendid.  What animal's skin did you use to make these, may I ask?  The stitch-work is very well done, and the texture of the leather has a rugged style to it.  I can tell you are a craftsman of skill!\n\nThank you, {name}, and here are your tickets." }
quests[79593] = { id = 79593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coarse Weightstone", progress = "It takes a lot of work to be the strongest woman alive!  My weight set is getting too light and if I'm too stay fit then I'll need more weights!\n\nDo you think you could bring me some weight stones?  If you do, then I'll give you a Darkmoon Faire ticket.", completion = "Great!  These will work great!  They're not too heavy, but not too light either.  They're perfect for building muscle mass!\n\nThanks much, {name}.  Here's your Darkmoon Faire ticket!" }
quests[79594] = { id = 79594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Copper Modulator", progress = "Yebb is developing a new attraction for the Zoo Bizarre, one that will drive people crazy with wonder, and delight!  But it will take a lot of work, and a lot of materials...\n\nThat includes copper modulators.  We need lots of modulators for the mechanical parts of the attraction.  Bring me copper modulators and I'll trade for them with a Darkmoon Faire ticket.", completion = "Aha!  The modulators!  Superb!\n\nI can't tell you exactly what we're building, but these will be invaluable for its construction.  I am in your debt, {name}, but please, take this Darkmoon Faire ticket as a token of my appreciation." }
quests[79595] = { id = 79595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carnival Boots", progress = "We at the Darkmoon Faire do much walking.  We walk from one faire site to another... in fact, you'll never see us sitting down on the job!  So it is no surprise that we wear out quite a lot of boots!  We need boots that are both durable and stylish, and embossed leather boots fit that bill rather well.\n\nYou!  You're a leatherworker; make me embossed leather boots and I'll give you a Darkmoon Faire ticket for the work.", completion = "Thank you, {name}.  These are quite well made.  The craftsmanship is top notch!  Here is a Darkmoon Faire ticket... enjoy, sir." }
quests[79624] = { id = 79624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anyone Can Cook", description = "The recipe appears to be for some sort of meat dish. It is written in a language you don't understand. Ogre is your best guess, given the source and subject matter.\n\nOgres aren't usually culinary types but, if you knew one with such an inclination, they could translate the recipe for you.", sourceObjective = "Find an ogre who can read the Illegible Recipe.", completion = "You have recipe? Skonk listening.", sourceObjectiveStatus = "unverified-source-field" }
quests[79626] = { id = 79626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Salvagematic 9000!", description = "This contraption seems to be receiving power, but just barely. A small plaque on the device reads \"The Salvagematic 9000\", followed by a bit of text that is indecipherable due to the thick layer of caked-on filth. The machine has a very large intake receptacle as well as a slot for coins to be inserted.", sourceObjective = "Insert a Grime-Encrusted Salvage into the Salvagematic 9000, and be sure to have thirty silver coins to start the machine.", progress = "The machine looks like it is in an exceptionally poor state of repair. It seems like you can still insert some Grime-Encrusted Salvage into the machine, but you aren't sure what will happen if you do.", completion = "You insert the Grime-Encrusted Salvage and thirty silver coins into the Salvagematic 9000.  The machine briefly illuminates, begins to shake and rattle, and then spits out your still-grimy salvage before falling silent. It seems to be broken.", sourceObjectiveStatus = "unverified-source-field" }
quests[79637] = { id = 79637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ticking Present", sourceObjective = "Have a joyous Feast of Great-Winter from your friends at Smokeywood Pastures.", sourceObjectiveStatus = "unverified-source-field" }
quests[79677] = { id = 79677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quick Grocery Run", description = "Other ogres laugh at Skonk because Skonk smaller than them. They say small ogre weak, so Skonk learn to cook instead of fight. This only cause more teasing, so Skonk run away to follow dream. \n\nSkonk can make dish, but need ingredients. Not sure where to find them. Skonk more focused on craft; not really logistics guy.", sourceObjective = "Gather the ingredients for Skonk's dish, then bring them to him in Arathi Highlands", progress = "You find ingredients yet? Almost dinner time.", completion = "Good work, {race} buddy. We really cooking now!", sourceObjectiveStatus = "unverified-source-field" }
quests[79678] = { id = 79678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taste Testing", description = "Ok {race} buddy, it time for Skonk favorite part. Skonk have fire hot and ready, and want to share new dish with new friend. You do such big favors for Skonk; it only right you get some too!\n\nLet Skonk know when you ready for tasting.", sourceObjective = "Taste test the recipe with Skonk.", completion = "Mmm, recipe is delicious!\n\nSkonk get a bit lost in passion of moment, but you were good helper! \n\nHere, this your share. Skonk even add little something extra for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[79704] = { id = 79704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Salvagematic 9000!", description = "Insert your salvage into the machine, get fabulous prizes! Probably. Maybe.", sourceObjective = "Insert a Grime-Encrusted Salvage into the Salvagematic 9000, and be sure to have three silver coins to start the machine.", progress = "The machine shudders and shakes before belching out a pile of salvaged parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[79705] = { id = 79705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Salvagematic", description = "I think that thing is on it's last legs, pal. I might be able to fix it, but it won't be easy... or cheap. Tell you what, bring me 10 mithril bars, 5 greater mystic essence, 3 GG12-082 cartridge fuses, and a Pristine G-7 C.O.R.E. processor, and I can probably fix it up for you. The cartridge fuses should be plentiful here in Gnomeregan, but the processor core is a pretty rare item and won't be too easy to find. You look pretty resourceful though, so I'm sure you'll figure it out! Good luck!", sourceObjective = "Bring Ziri \"The Wrench\" 10 Mithril Bars, 5 Greater Mystic Essence, 3 GG12-082 Cartridge Fuses, and a Pristine G-7 C.O.R.E. Processor and she can get the Salvagematic 9000! working for you. Probably. Maybe.", progress = "Wow you actually hauled all that junk back here? I was mostly just messing with you, but hey, I'm a gnome of my word and I'm not one to waste good materials. Give me a bit and I'll get this baby back up and running!", completion = "One Salvagematic 9000 ready to rock, as promised. If you happen to get anything good out of there, come see me. I might be able to teach you a thing or two, for a price of course! \n\n<Ziri grins widely and shoves something into her back pocket>", sourceObjectiveStatus = "unverified-source-field" }
quests[79731] = { id = 79731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll Scroll", description = "<The ancient glyphs resolve into words before your eyes.>\n\nWhen Zul'Kunda's fountain runs with the waters of the holy spring, the gods grant their blessing.", sourceObjective = "Solve the riddle of the scroll. Once you've done that, Hemet Nesingwary might like to hear the tale.", completion = "A magic fountain hidden in the jungle? What a story, {name}!\n\nThat gives me an idea for another chapter in my book! Let's see, where did I put that manuscript...", sourceObjectiveStatus = "unverified-source-field" }
quests[79905] = { id = 79905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Knowledge", sourceObjective = "With the knowledge you've gained in your travels, I believe you're ready to learn to conjure Comprehension Charms on your own. This will help you uncover new texts for the library's collection.\n\nSafe travels, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79939] = { id = 79939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Hammer", description = "An ornate broken warhammer lies surrounded by dead Burning Blade Cultists and Scarlet Crusade warriors. A fight clearly happened here, and fairly recently. You also recognize this as the weapon of a paladin of the Order of the Silver Hand. While you've seen many hammers like this one, the quality and worksmanship of this weapon is fairly unique. You should search the area for clues, and find someone who may know more about this weapon.", sourceObjective = "Search for clues about what happened at the Mannoroc Coven in Desolace, and find someone who may know more about the broken hammer.", progress = "What is it you have there, my friend?", completion = "<Katherine sighs heavily> Yes {name}, I do know of this weapon. I'd assumed its owner had died long ago.", sourceObjectiveStatus = "unverified-source-field" }
quests[79940] = { id = 79940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Brother", description = "<Katherine winces as she holds the shattered fragments of the broken hammer> \n\nI won't speak of this weapon's master in detail for the telling would fill me with shame, but I'll tell you what I can.", sourceObjective = "Speak with Katherine the Pure and learn more about the broken hammer.", completion = "You have few clues to go on so it may be difficult to find Aeonas, but you should try.", sourceObjectiveStatus = "unverified-source-field" }
quests[79945] = { id = 79945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from the Grand Crusader", description = "This appears to be orders from the Grand Crusader of the Scarlet Crusade himself, Dathrohan. It seems that Aeonas has run afoul of the Crusade. Judging by the scene before you, it appears that the Crusade was able to follow Aeonas here and apprehend him. It appears that he did not go down without a fight.\n\nThe charges levied against Aeonas are grave, but that would explain some of the scene you came upon in Desolace.", sourceObjective = "Bring the Orders from the Grand Crusader back to Katherine the Pure.", progress = "Do you bring word of Aeonas?", completion = "<Katherine frowns deeply as she reads the letter>\n\nAeonas held some radical views by the time he left the order, but I find it very hard to believe that his business in Desolace involved consorting with demons, undead, or anything of the sort. We need to find him and hear his side of this. There's more to this, I'm certain of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[79946] = { id = 79946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brother In Need", description = "Due to the... unforunate nature of why he left the order, it would be bad comedy for Aeonas to die at the hands of the Scarlet Crusade now. The Crusade is an organization of zealots and lunatics and they've been growing increasingly brazen in their willingness to commit violence against anyone who they imagine to be enemies of the light. Go to the Scarlet Monastery in Tirisfal Glades and find out if Aeonas still lives.", sourceObjective = "Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery", completion = "<Aeonas looks critically injured. He struggles to choke out a few words.> They didn't even... ask me any questions...", sourceObjectiveStatus = "unverified-source-field" }
quests[79947] = { id = 79947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geomancy: The Stone-Cold Truth", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79948] = { id = 79948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defensive Magics 101", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79949] = { id = 79949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Web of Lies: Debunking Myths and Legends", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79950] = { id = 79950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons and You", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79951] = { id = 79951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mummies: A Guide to the Unsavory Undead", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79952] = { id = 79952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RwlRwlRwlRwl!", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79953] = { id = 79953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ludite's Guide to Caring for Your Demonic Pet", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[79963] = { id = 79963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By The Light's Grace", description = "Aeonas needs immediate healing or he will die. Call upon the light and save him.", sourceObjective = "Heal Aeonas.", completion = "<Aeonas seems to be breathing more easily now. He still seems quite weak, but he manages to turn his head towards you to speak.>\n\nYou say that Katherine sent you? Bless that woman. Thank you, {class}. I am in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79970] = { id = 79970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aeonas the Vindicated", description = "Thank you for saving me, {class}. It seems that I'm not as young as I once was, and I think I'm going to need allies for what is to come. Please, meet me in Stormwind in the Cathedral of Light as soon as you are able.\n\nDon't worry about me, I can find my way out of here on my own. I just need a few moments to recover my strength", sourceObjective = "Meet Aeonas at the Cathedral of Light in Stormwind.", completion = "I can't thank you enough for rescuing me from that light-forsaken place. Sadly, I fear that this is just the beginning of our journey, and the rest won't be easy. Let us speak and plan our next steps.\n\nOh, but first... allow this old man to pass on some of his knowledge to the younger generation. It's not much of a reward, but I hope you can put it to good use none the less.", sourceObjectiveStatus = "unverified-source-field" }
quests[79974] = { id = 79974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wet Job", description = "Always like to keep a reserve stash nearby in the off chance I've got to flee in a hurry.\n\nThe face of this mountainside is so beautiful you might say it was carved from the waterfalls of time. \nThat's the eagles nest, that's what you're looking for.", sourceObjective = "Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies.", completion = "Dwarven Engineering, always a marvel.", sourceObjectiveStatus = "unverified-source-field" }
quests[79975] = { id = 79975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle's Fist", description = "You find a carefully folded letter inside of the toolbox. Imagining a voice speaking, you read: \"From here, with the right tools, you call the shots. Great place to launch a parachute glider.\n\nMy loyalty to the Eagle and Fist requires distance in order to serve them best. This barricade has had better days, like the Old Kingdoms it once defended, but I'll never abandon it.\"", sourceObjective = "Water spray dampens the air, the view is incredible.", completion = "A campfire is newly fed with wood, but signs of a quick departure are evident.", sourceObjectiveStatus = "unverified-source-field" }
quests[79976] = { id = 79976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Must Be The Place", description = "\"So, I've decided to take my work back underground. To stop it falling into the wrong hands.\"\n\nThe paper is torn just large enough to fit the message. You aren't sure if these are the last words you'll read from the author, or if they're a clue to the next hideout. An inadequately secured sleeping bag is unrolling itself onto your feet...", sourceObjective = "Whoever was here, you just missed them.", completion = "Heavy canvas is rolled over assorted equipment. You help yourself to the pack.", sourceObjectiveStatus = "unverified-source-field" }
quests[79980] = { id = 79980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scramble", description = "Not so bad, eh? Since you're reading this, it means my stash is still there. Take a hundred paces due north and don't break your ankles going down the steep cliffside. There should be enough to keep you going.", sourceObjective = "Find what awaits you.", completion = "You pull a messenger bag out of the ground. Stuffed in with the supplies is a dirty parchment.", sourceObjectiveStatus = "unverified-source-field" }
quests[79981] = { id = 79981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corroded Core", description = "This C.O.R.E. unit definitely fits the description that Ziri gave you, but it's badly damaged and covered in gunk. You can barely make out a faded sticker with what appears to be contact information for some sort of warranty. Only a few letters are visible. \n\n\"Limi... arranty... claims contac.... Wi..... nde...ar\"", sourceObjective = "Find someone who can repair the Corroded G-7 C.O.R.E Processor.", progress = "When someone builds a tower and workshop on top of a giant spire in the middle of nowhere, it's almost like they don't want unexpected visitors. Who'd have thought?", completion = "<Wirdal's magnifying goggles make a low mechanical buzzing noise as they focus on the Corroded G-7 C.O.R.E. Processor in your hand> Indeed, that's one of mine. \n\nI strongly suggest that you throw that thing into the ocean and never think of it again.", sourceObjectiveStatus = "unverified-source-field" }
quests[79982] = { id = 79982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warranty Claim", description = "I can repair that processor for you, but I need a somewhat hard-to-get item; a Charged Voidcore. Naga spell casters are known to carry these and while I can't be sure where the Naga get them or how they are made, they tend to act as powerful foci for certain types of magical rituals. They are the key component to my G-7 C.O.R.E. Processor unit. They aren't common so you may be in for a tough time finding one.", sourceObjective = "Bring Wirdal Wondergear a Charged Voidcore.", progress = "I shudder to think how many Naga you had to clobber to get this thing.", completion = "Well here goes nothing. \n\nI feel compelled to give you the disclaimer that I won't be held responsible for any electrical fires, electromagnetic pulse bursts, demonic manifestations, or interdimensional vortexes that may result from the installation and usage of this processor.", sourceObjectiveStatus = "unverified-source-field" }
quests[79984] = { id = 79984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quadrangulation", description = "Wirdal? Yeah I know him. He's a gnome, but I won't hold that against him as a fellow transpolyportion enthusiast like myself.  He took off outta here a few months back for somewhere in Kalimdor, but he 'ports in every now and then to grab supplies. I could probably transpolyport you to him, but you'd need his coordinates or I'd probably just teleport you into a mountain or something. If you can find his quadrangulation beacons in Kalimdor and attuned to them, that would do the trick!", sourceObjective = "Find Wirdal Wondergear's Quadrangulation Beacons and attune with them. There are four of them and they are located somewhere in Kalimdor.", progress = "Did you find the beacons?", completion = "Wow, you found 'em. Give me a second to plug in the coordinates and calibrate the transponder.... \n\n... and there we go! I think that should do the trick.", sourceObjectiveStatus = "unverified-source-field" }
quests[79985] = { id = 79985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fine Mess", description = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, {name}!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", sourceObjective = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", completion = "I suppose you should be rewarded for bringing Kernobee back to us in one piece, {name}. If you go back to Gnomeregan, these might give you the edge you'll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg.", sourceObjectiveStatus = "unverified-source-field" }
quests[79986] = { id = 79986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grime-Encrusted Ring", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", sourceObjective = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", progress = "The gnomish contraption before you bears a plaque calling it \"The Sparklematic 5200\".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.\n\nIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!", completion = "You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.\n\nPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...\n\nThe machine suddenly stops, trumpeting its cessation with a simple \"Ding!\"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!", sourceObjectiveStatus = "unverified-source-field" }
quests[79987] = { id = 79987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", sourceObjective = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", progress = "Hey, easy there partner - I'm a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord.\n\nWell, of course you aren't - silly me!  You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!\n\nUm... what do you need?", completion = "A ring, you say?  Let's see... yep, I made that ring by golly.\n\nBefore Gnomeregan went up, I had a small shop there.  Perhaps it's one I left behind when I ran for the hills; it's a simple design, and I made several like it.  Maybe it's from someone who didn't make it out.\n\nDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it's wasted on the likes of me.\n\nNow, back to the ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[79990] = { id = 79990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Lumber", description = "We are in desperate need of additional resources and reinforcements to support our objectives in Arathi Basin. Appropriate lumber has been particularly difficult to obtain and we've been forced to look as far as Stranglethorn Vale to source what we need. Bring me a Shipment of Stranglethorn Lumber and your support will not be overlooked.", sourceObjective = "Bring Sergeant Maclear a Shipment of Stranglethorn Lumber.", progress = "Have you brought us fresh supplies?", completion = "Thank you {class}. This will help us turn the tide in Arathi Basin.", sourceObjectiveStatus = "unverified-source-field" }
quests[79991] = { id = 79991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranglethorn Lumber", description = "We are in desperate need of additional resources and reinforcements to support our objectives in Arathi Basin. Appropriate lumber has been particularly difficult to obtain and we've been forced to look as far as Stranglethorn Vale to source what we need. Bring me a Shipment of Stranglethorn Lumber and your support will not be overlooked.", sourceObjective = "Bring Deathstalker Mortis a Shipment of Stranglethorn Lumber.", progress = "Have you brought us fresh supplies?", completion = "Thank you {class}. This will help us turn the tide in Arathi Basin.", sourceObjectiveStatus = "unverified-source-field" }
quests[80001] = { id = 80001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekindle", progress = "An extinguished fire pit. The wood is even dry enough to catch a flame.", completion = "You put your scout skills to work." }
quests[80098] = { id = 80098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Dalaran Relic", progress = "Have you recovered one of the stolen relics?", completion = "Thank you, {name}. I will make sure this is safely returned to the city." }
quests[80120] = { id = 80120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Service to Dalaran", sourceObjective = "You have done a great service for Dalaran, and for Azeroth.\n\nOur laws prohibit me from sharing Dalaran's secrets with outsiders, but I think I can stretch the rules a bit to reward you for your efforts. Please, take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[80131] = { id = 80131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Improvement", description = "Listen {name}, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", sourceObjective = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.", progress = "Do you have the materials I need?  I wouldn't ask you for them if I wasn't down on my luck...", completion = "Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I'd normally charge ten times what I have charged you for a ring of this quality...\n\nSpeaking of rings, here's your new one!", sourceObjectiveStatus = "unverified-source-field" }
quests[80132] = { id = 80132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rig Wars", description = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, {name}!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, {name}. Then crack open that safe and bring back those blueprints!", sourceObjective = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", progress = "I don't see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?", completion = "I knew you could do it, {name}! Sovik on the other hand, he had his doubts.\n\n\n\nNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models.", sourceObjectiveStatus = "unverified-source-field" }
quests[80133] = { id = 80133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Scooty", description = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, {name}. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", sourceObjective = "Speak with Scooty in Booty Bay.", completion = "She's a beauty, isn't she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.\n\nDon't worry, {name}, I've got her all fixed up. She won't blow up on you - and if she does, it'll be quick and painless.", sourceObjectiveStatus = "unverified-source-field" }
quests[80134] = { id = 80134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomer-gooooone!", description = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", sourceObjective = "Wait for Scooty to calibrate the Goblin Transponder.", completion = "All done! When you're ready, just step on the pad.", sourceObjectiveStatus = "unverified-source-field" }
quests[80135] = { id = 80135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort's Essentials", description = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", sourceObjective = "Speak with Klockmort Spannerspan in Ironforge.", completion = "I do!  I do need help with a mission into Gnomeregan.  And you're just the {class} to do it!", sourceObjectiveStatus = "unverified-source-field" }
quests[80136] = { id = 80136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essential Artificials", description = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, {name}, and please hurry!", sourceObjective = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", progress = "Do you have the essential artificials?", completion = "You got them!  Now I can begin my new experiments!\n\nI can't thank you enough, {name}!  You're bravery has advanced gnomish research by a leap and a bound!", sourceObjectiveStatus = "unverified-source-field" }
quests[80137] = { id = 80137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Techbot's Brain!", description = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.", sourceObjective = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", progress = "Did you find Techbot?  Did you retrieve its memory core??", completion = "Oh, this is wonderful!  Thank you, {name}!  I'll get to work immediately!!\n\nPoor, poor Techbot... Don't feel bad.  We'll get you fixed.\n\nNow, where did I put that plug for my hydro-jack swivel spanner...", sourceObjectiveStatus = "unverified-source-field" }
quests[80138] = { id = 80138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinkmaster Overspark", description = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.", sourceObjective = "Speak with Tinkmaster Overspark in Ironforge.", completion = "Yes it's true.  Techbot has gone rogue!  Please, can you help me?", sourceObjectiveStatus = "unverified-source-field" }
quests[80139] = { id = 80139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnogaine", description = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, {name}.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", sourceObjective = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", progress = "Can't you see we're trying to cure an entire species of gnomes here??! We need more of the green glow!", completion = "Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!", sourceObjectiveStatus = "unverified-source-field" }
quests[80140] = { id = 80140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", sourceObjective = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", progress = "You'd think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?", completion = "A ring from Gnomeregan?  Let's see... not mine, but interesting.\n\nThe Gnomeregan thing - couldn't have happened to a nicer bunch of numbskulls.  For years they're a joke, and now almost overnight they're making better rigs than us?\n\nDark Iron dwarves had the ring?  That's even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they'd definitely want some major payback.  It's certainly worth investigating.\n\nYou know, about that ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[80141] = { id = 80141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nogg's Ring Redo", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", sourceObjective = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.", progress = "Do you have the materials I need?  I can't improve on this design without everything I asked for.", completion = "Here's your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration.", sourceObjectiveStatus = "unverified-source-field" }
quests[80142] = { id = 80142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castpipe's Task", description = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", sourceObjective = "Speak with Master Mechanic Castpipe in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[80143] = { id = 80143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Rescue", description = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you help?", sourceObjective = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", progress = "Do you have the prismatic punch card??", completion = "You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!\n\nYour service to the gnomes will be long remembered, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80147] = { id = 80147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Dalaran Relic", progress = "Have you recovered one of the stolen relics?", completion = "Thank you, {name}. I will make sure this is safely returned to the city." }
quests[80148] = { id = 80148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Dalaran Relic", progress = "Have you recovered one of the stolen relics?", completion = "Thank you, {name}. I will make sure this is safely returned to the city." }
