quests[80151] = { id = 80151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Dalaran Relic", progress = "Have you recovered one of the stolen relics?", completion = "Thank you, {name}. I will make sure this is safely returned to the city." }
quests[80152] = { id = 80152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Dalaran Relic", progress = "Have you recovered one of the stolen relics?", completion = "Thank you, {name}. I will make sure this is safely returned to the city." }
quests[80153] = { id = 80153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", sourceObjective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in a frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", sourceObjectiveStatus = "unverified-source-field" }
quests[80155] = { id = 80155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sparklematic Action", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
quests[80156] = { id = 80156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", sourceObjective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", sourceObjectiveStatus = "unverified-source-field" }
quests[80157] = { id = 80157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", sourceObjective = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", sourceObjectiveStatus = "unverified-source-field" }
quests[80158] = { id = 80158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", sourceObjective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", sourceObjectiveStatus = "unverified-source-field" }
quests[80160] = { id = 80160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sparklematic Action", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
quests[80161] = { id = 80161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", sourceObjective = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", sourceObjectiveStatus = "unverified-source-field" }
quests[80164] = { id = 80164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Large Cluster Rockets", progress = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", completion = "Thank you, {name}.  Here is the recipe for large cluster rockets.  May your products bring joy and luck to all those who gaze up them." }
quests[80165] = { id = 80165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Rockets", progress = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", completion = "Here you are, {name}.  Take these recipes and learn their secrets.  I bid you fortune, and I look forward to seeing your magnificent creations." }
quests[80166] = { id = 80166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Rockets", progress = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", completion = "Ah, very well.  Here are your recipes, {name}, and my Elune bless you." }
quests[80167] = { id = 80167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Large Rockets", progress = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, {name}, and I shall share the knowledge of their creation.", completion = "Very well - I accept these coins of ancestry.  Here are your recipes, {name}.  May you use them to spread Elune's glory!" }
quests[80168] = { id = 80168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firework Launcher", progress = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", completion = "Here you are, {name}.  Here is the schematic to create a firework launcher.  Place launchers where you wish to celebrate, and then welcome your friends to join you!" }
quests[80169] = { id = 80169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Launcher", progress = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", completion = "Here is your schematic.  Study it closely, and learn...\n\nGood luck, {name}.  May your celebrations rival that of the Lunar Festival itself!" }
quests[80170] = { id = 80170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Recipes", progress = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, {name}, then I will give you the pattern to create traditional red dresses or suits.", completion = "Here are the patterns, {name}.  I am sure you will find the product of this knowledge quite beautiful." }
quests[80180] = { id = 80180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Betrayal", description = "I trusted Thermaplugg, {race}. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, {name}. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", sourceObjective = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", completion = "I like to think that the last thing that went through his head as he collapsed to the ground was your foot, {race}. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality.", sourceObjectiveStatus = "unverified-source-field" }
quests[80181] = { id = 80181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyrodrillmatic Excavationators", description = "It's terrible, {name}. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, {name}. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", sourceObjective = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", progress = "If this were a race, you would have lost by now.", completion = "This will do nicely, {name}. One gyrodrillmatic excavationator fixed; 398 left to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[80182] = { id = 80182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Cure is More Green Glow", description = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", sourceObjective = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.\n\nOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", progress = "Hrm, you're not glowing. That's a good sign.", completion = "<Ozzie examines you.> Impressive, you still have all of your limbs. Now it's time to see what this stuff can do!", sourceObjectiveStatus = "unverified-source-field" }
quests[80241] = { id = 80241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Origins of Smithing", description = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, {name}.", sourceObjective = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.", progress = "Could you be the next Galvan protege?", completion = "Very good, {name}! Listen and learn.\n\nBlacksmithing never comes from here! \n\nBlacksmithing never comes from here! \n\nBlacksmithing only comes from here! \n\nAnd now you know the origin of blacksmithing.", sourceObjectiveStatus = "unverified-source-field" }
quests[80307] = { id = 80307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[80308] = { id = 80308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[80309] = { id = 80309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Full Shipment", progress = "Do you have something for me?", completion = "Everything's accounted for! Thank you, {name}. These supplies are critical for the front lines." }
quests[80324] = { id = 80324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mad King", description = "You find a dirty, tattered notebook full of scribbled schematics and notes. It's quite clear even after just a cursory glance that any of these creations could be used to wreak terrible havoc should anyone ever be foolish enough to build them.", sourceObjective = "Bring Thermaplugg's Engineering Notes to High Tinker Mekkatorque at Tinker Town in Ironforge.", progress = "{name}, what is it you have there?", completion = "I can't thank you enough for recovering these schematics. I shudder to think what would have become of Ironforge  had Thermaplugg been able to bring these creations to bear against us. \n\nThis calls for a celebration!", sourceObjectiveStatus = "unverified-source-field" }
quests[80325] = { id = 80325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mad King", description = "You find a dirty, tattered notebook full of scribbled schematics and notes. It's quite clear even after just a cursory glance that any of these creations could be used to wreak terrible havoc should anyone ever be foolish enough to build them.", sourceObjective = "Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar.", progress = "Whatcha got for me?", completion = "<Nogg's eyes light up as he reads through the collection of notes and schematics>\n\nI am going to blow so many things up with this stuff. \n\nGood job, {name}. I think this calls for a celebration!", sourceObjectiveStatus = "unverified-source-field" }
quests[80411] = { id = 80411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Talisman of Kazdor", description = "From the most recent letter we intercepted, it appears the final artifact Caius desires is the Talisman of Kazdor. The letter states this talisman is somewhere inside Zul'Farrak. \n\nI want you to complete the job as per Caius' instructions, as not to arouse his suspicion. This means you'll have to go into Zul'Farrak alone, as usual.  \n\nHowever, before you deliver the Talisman, bring it back here. We'll be giving Caius a little more than he asked for.", sourceObjective = "Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone.", progress = "Go now, time is of the essence.", completion = "Some fine thievery indeed, {name}. Now, time for step two.", sourceObjectiveStatus = "unverified-source-field" }
quests[80417] = { id = 80417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Bushy Tails", progress = "It's amazing what people value!  Take, for instance, a wooden stick with a soft bushy tail attached to it.  Now, you and I might think something like that isn't all that valuable... but if you give that piece of junk a neat name like \"Savage Fuzz Tail\" and put it in a pretty box, then people will think it's valuable.  Trash becomes treasure!\n\nGet me soft bushy tails from the wolves of Desolace and the Badlands, and I'll give you Darkmoon Faire tickets.", completion = "Well done, {name}!  These tails will make great prizes for our visitors, and that means happy visitors... who talk to their friends and bring more visitors!\n\nHere are your tickets!  Have a good time at the Darkmoon Faire... and don't forget to tell your friends about us!" }
quests[80421] = { id = 80421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Iron Bracers", progress = "I'm working on a new costume, for when I have my own booth as the strongest woman alive!  Right now I'm looking for some bracers I can wear.  They can't cover much because people want to see my muscles, but I still want to flash a little color, you know?\n\nHow about green iron bracers, {name}?  Can you make me green iron bracers?  If you can, then I have a whole bunch of Darkmoon Faire tickets for you.", completion = "Yes!  These are exactly what I need!  Such a lovely color, and they still leave my arms bare so you can see how strong they are!  Perfect!\n\nHere you are, {name}.  Here are your tickets - enjoy!" }
quests[80422] = { id = 80422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Fireworks", progress = "When I finally get this booth up and running, I'll want to advertise!  And what better way is there to advertise then with fireworks?\n\nWell, some might think that the smell of a cauldron, churning with the boiling heads of your foes is better for drawing crowds, but... we're in mixed company.  So fireworks it will have to be!\n\nBring me green fireworks, {name}, and I have a big fistful of Darkmoon Faire tickets for you.", completion = "You brought the fireworks.  Wonderful work, {name}!  I can't wait to light these and tell the world that my booth is ready to go!  I must still wait, quite a long time I'm afraid, but... I'll be ready when I'm ready, yes?\n\nHere are the tickets, {name}.  Enjoy yourself!" }
quests[80423] = { id = 80423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World's Largest Gnome!", progress = "Yebb Nebblegear is looking to add more talent to his show, and he's searching far and wide for the world's largest gnome.  Do you know any gnomes of considerable size?\n\nWell before he finds the gnome, he wants to have its costume ready.  I think a barbaric harness would be a good foundation for the costume; can you make some harnesses and bring them to me?  Do that, and I'll have a stack of Darkmoon Faire tickets for you...", completion = "Oh dear, these are quite large!!  I can't imagine finding a gnome that would fit snuggly into them, but not to worry - if the gnome we find is not big enough, I can make adjustments to his costume.\n\nMany thanks, {name}.  Here are the tickets I promised you." }
quests[80453] = { id = 80453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Laid Plans", description = "Take the talisman down to Zan Shivsprocket, in the basement. I've asked him to rig the artifact with a mechanism that will detect any attempt to channel magic energy into, or out of, it.\n\nThe mechanism is all but invisible to the naked eye, and will detonate when triggered. With any luck, Caius will be killed in the blast. At the very least, his plans for the talisman will be foiled.", sourceObjective = "Bring the Talisman of Kazdor to Zan Shivsprocket in the basement of Ravenholdt Manor.", progress = "Yes, {class}? Do you need something from me?", completion = "So you're on Fahrad's job, hm?  Very well. Give me the talisman and I'll get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[80454] = { id = 80454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Drop", description = "The bait is ready, now we must lay the trap. I've modified the talisman per Fahrad's instructions. All that's left is for you to deliver it as you have the other artifacts before.\n\nGo to the cabin near Pyrewood Village, and put this modified talisman into Caius' dead drop.\n\nWhat follows is out of our hands, for now.", sourceObjective = "Take the Modified Talisman to Caius' dead drop near Pyrewood Village.", progress = "<The chest sits, empty.>", completion = "<You place the Modified Talisman into the chest.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80455] = { id = 80455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biding Our Time", description = "The job is done. Better return to Ravenholdt and notify Fahrad.", sourceObjective = "Report back to Fahrad at Ravenholdt Manor.", completion = "It seems all has gone according to plan. Good work.\n\nAll we can do now is wait for Caius to make his next move. I will notify you when that time comes. Your commitment to the manor has not been entirely fulfilled.\n\nFor now, however, you can rest easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[80526] = { id = 80526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool Me Twice", description = "Not a moment too soon, {name}\n \nThe manor has been keeping tabs on this \"C\" character you've been dealing with. \n \nC's true identity is Caius Blackwood; a powerful magic user working with the Syndicate. Our sources say he has been gathering artifacts for an unknown purpose. Only recently did we discover *you* were the one providing them.\n \nCaius must be stopped, and I believe the onus of doing so falls on you. Fortunately, I've devised a plan. Come speak to me when you're ready to clear your name.", sourceObjective = "Speak to Fahrad when you're ready to hear his plan.", completion = "Alright then, let's get down to business.", sourceObjectiveStatus = "unverified-source-field" }
quests[81570] = { id = 81570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a moonsteel broadsword.  I call it a swing blade.\n\nYou help me?  Maybe you find it in town, maybe you talk to a blacksmith and he'll make it special.\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", sourceObjective = "Bring a Moonsteel Broadsword to Jarl in Dustwallow Marsh.", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[81682] = { id = 81682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Champ", description = "This arena may not look like much, but I'll tell ya, this place used to be quite the attraction. Prize fighters, adventurers, even a few cartel folks, would all step into the ring for a chance at coin and glory. \n\nBetween the gambling and concessions, I was making a killing!\n\nThings started to die down after the old champ, Kajind, retired, though. He was a real serious type; left for Azshara one day without a word. If you found him, we could get the arena back up and running again.", sourceObjective = "Find Kajind somewhere in Azshara.", completion = "<A wistful expression briefly crosses Kajind's face>\n\nIndeed, I am the so-called \"champ\" you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[81697] = { id = 81697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defanged", description = "Battle is all I know, {name}. During the third war, countless fell before my blade. When the war ended, I made my way as a prize fighter. That is when I came upon the arena of Gadgetzan.\n\nMy days there were glorious, but I soon tired of being champion. I came to Azshara in search of a greater challenge; a blue drake who roams south-east of here. Alas, the creature got the better of me. I escaped alive, but my blade was taken for its hoard.\n\nIf you recover my blade, I will return with you to Gadgetzan.", sourceObjective = "Retrieve Kajind's blade from the blue drake roaming south-east of Forlorn Ridge in Azshara.", progress = "I do not fault your hesitation, {race}. The drake is a fearsome foe.", completion = "Where once I failed, you have succeeded. You have my deepest respect and gratitude, {name}. Perhaps you will best me in the arena as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[81716] = { id = 81716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover Incursion Field Report: Duskwood", description = "Thank Elune you're here, {name}.  We've been overrun with demons coming through the Emerald Dream Gate. I've been cut off from my scout there. Please find Scout Charla by the Dream Gate and come back with her field report. And along the way, kill a few of those swarming demons. Once you get back with the report, I'll give you a follow-up mission to act on that intelligence.", sourceObjective = "Kill demons and return the field report to Field Captain Palandar.", progress = "You have the report?", completion = "Thank you, {name}! Based on the intelligence you've recovered, I have this follow-up mission for you. Thank you for all your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[81727] = { id = 81727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover Incursion Field Report: Ashenvale", description = "Thank Elune you're here, {name}.  We've been overrun with demons coming through the Emerald Dream Gate. I've been cut off from my scout there. Please find Scout Gemeron by the Dream Gate and come back with his field report. And along the way, kill a few of those swarming demons. Once you get back with the report, I'll give you a follow-up mission to act on that intelligence.", sourceObjective = "Kill demons and return the field report to Field Captain Hannalah.", progress = "You have the report?", completion = "Thank you, {name}! Based on the intelligence you've recovered, I have this follow-up mission for you. Thank you for all your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[81728] = { id = 81728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover Incursion Field Report: Hinterlands", description = "Thank Elune you're here, {name}.  We've been overrun with demons coming through the Emerald Dream Gate. I've been cut off from my scout there. Please find Scout Fallia by the Dream Gate and come back with her field report. And along the way, kill a few of those swarming demons. Once you get back with the report, I'll give you a follow-up mission to act on that intelligence.", sourceObjective = "Kill demons and return the field report to Field Captain Korlian.", progress = "You have the report?", completion = "Thank you, {name}! Based on the intelligence you've recovered, I have this follow-up mission for you. Thank you for all your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[81729] = { id = 81729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover Incursion Field Report: Feralas", description = "Thank Elune you're here, {name}.  We've been overrun with demons coming through the Emerald Dream Gate. I've been cut off from my scout there. Please find Scout Thandros by the Dream Gate and come back with his field report. And along the way, kill a few of those swarming demons. Once you get back with the report, I'll give you a follow-up mission to act on that intelligence.", sourceObjective = "Kill demons and return the field report to Field Captain Arunnel.", progress = "You have the report?", completion = "Thank you, {name}! Based on the intelligence you've recovered, I have this follow-up mission for you. Thank you for all your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[81730] = { id = 81730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission I: Defeat Worgen", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion in the Rotting Orchard. Defeat worgen there and return to me.", sourceObjective = "Defeat 10 Nightmare Runners and 10 Nightmare Weavers in the Duskwood Nightmare Incursion in the Rotting Orchard and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81731] = { id = 81731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission II: Defeat Ogres", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Defeat ogres there and return to me.", sourceObjective = "Defeat 3 Deranged Ogres and 3 Demented Fire Weavers in the Duskwood Nightmare Incursion at the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You've dealt with the ogres?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81732] = { id = 81732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission III: Defeat Dragonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead. Defeat dragonkin there and return to me.", sourceObjective = "Defeat 3 Wyrmkin Terrorwalkers and 10 Nightterror Whelps in the Duskwood Nightmare Incursion at the Yorgen Farmstead and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81733] = { id = 81733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission IV: Ogre Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Retrieve an intelligence report from Dreamwarden Thalinar there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Thalinar in the Duskwood Nightmare Incursion deep inside the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81734] = { id = 81734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission V: Worgen Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Retrieve an intelligence report from Dreamwarden Dorilar there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Dorilar in the Duskwood Nightmare Incursion in the barn at the Rotting Orchard and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81735] = { id = 81735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission VI: Dragon Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead . Retrieve an intelligence report from Dreamwarden Amalia there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Amalia in the Duskwood Nightmare Incursion in the farmhouse at the Yorgen Farmstead and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81736] = { id = 81736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission VII: Recover Shadowscythe", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Retrieve a powerful artifact known as the Shadowscythe and deliver it to me.", sourceObjective = "Recover the Shadowscythe in the Duskwood Nightmare Incursion upstairs in the farmhouse at the Rotting Orchard and return to Field Captain Palandar.", progress = "You have the Shadowscythe?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81737] = { id = 81737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission VIII: Recover Ogre Magi text", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Retrieve an Ogre Magi Text and deliver it to me.", sourceObjective = "Recover an Ogre Magi Text in the Duskwood Nightmare Incursion within the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You have the text?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81738] = { id = 81738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission IX: Recover Dragon Egg", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead. Retrieve an Unhatched Green Dragon Egg and deliver it to me.", sourceObjective = "Recover an Unhatched Green Dragon Egg in the Duskwood Nightmare Incursion from the Yorgen Farmstead near the large stump in the fields and return to Field Captain Palandar.", progress = "You have the egg?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81739] = { id = 81739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission X: Nightmare Moss", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove and collect Nightmare Moss from within the Nightmare Incursions. We can harness its magic to reverse the damage. You will need the assistance of an herbalist.", sourceObjective = "Gather 10 Nightmare Moss in the Duskwood Nightmare Incursions and return to Field Captain Palandar.", progress = "You have the Nightmare Moss?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81740] = { id = 81740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XI: Cold Iron Ore", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove and collect Cold Iron Ore from within the Nightmare Incursions. We can harness its magic to reverse the damage. You will need the assistance of a miner.", sourceObjective = "Gather 10 Cold Iron Ore in the Duskwood Nightmare Incursions and return to Field Captain Palandar.", progress = "You have the Cold Iron Ore?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81741] = { id = 81741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XII: Dream-Touched Dragonscale", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove and collect Dream-Touched Dragonscales from dragonkin within the Nightmare Incursions. We can harness its magic to reverse the damage. You will need the assistance of a skinner.", sourceObjective = "Gather 10 Dream-Touched Dragonscales in the Duskwood Nightmare Incursions and return to Field Captain Palandar.", progress = "You have the Dragonscales?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81742] = { id = 81742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XIII: Defeat Ylanthrius", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead. Defeat the dragon Ylanthrius there and return to me.", sourceObjective = "Defeat Ylanthrius in the Duskwood Nightmare Incursion at the Yorgen Farmstead field and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81743] = { id = 81743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XIV: Defeat Vvarc'zul", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Defeat the ogre warlord Vvarc'zul there and return to me.", sourceObjective = "Defeat Vvarc'zul in the Duskwood Nightmare Incursion deep in the Vul'gol Ogre Mound and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81744] = { id = 81744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XV: Defeat Amokarok", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Defeat the worgen leader Amokarok there and return to me.", sourceObjective = "Defeat Amokarok in the Duskwood Nightmare Incursion at a campsite near the barn in the Rotting Orchard and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81745] = { id = 81745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XVI: Rescue Kroll Mountainshade", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Find the sleeping Druid of the Claw Kroll Mountainshade there and escort him to safety. Then return to me.", sourceObjective = "Rescue Kroll Mountainshade from the Duskwood Nightmare Incursion in the guest house at the Rotting Orchard and return to Field Captain Palandar.", progress = "You rescued Kroll?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81746] = { id = 81746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XVII: Rescue Alara Grovemender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Darmstead. Find the sleeping Druid of the Claw Alara Grovemender there and escort her to safety. Then return to me.", sourceObjective = "Rescue Alara Grovemender in the Duskwood Nightmare Incursion in the stable at the Yorgen Farmstead and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81747] = { id = 81747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Mission XVIII: Rescue Elenora Marshwalker", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Find the sleeping Druid of the Claw Elenora Marshwalker there and escort her to safety. Then return to me.", sourceObjective = "Rescue Elenora Marshwalker in the Duskwood Nightmare Incursion in the ruins of a farmhouse near the Vul'gol Ogre Mound and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81762] = { id = 81762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Good News", description = "Greetings, {name}. I have good news. I've made contact with my friend, and I am leaving soon to meet with him. What's more, another orb has surfaced in Kalimdor.  I cannot be in two places at once so if you are willing, I'd like for you to go in my stead to follow up on this new orb. Speak with Katherine for further instructions.", sourceObjective = "Speak with Katherine the Pure at the Cathedral of Light in Stormwind.", completion = "Good to see you again, {name}. Let's get you caught up.", sourceObjectiveStatus = "unverified-source-field" }
quests[81764] = { id = 81764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Merchant", description = "Well met again, {name}. Shaw and his spies have provided us with information on a mysterious merchant who just arrived in Kalimdor and is looking to offload a collection of dangerous artifacts. We've come to believe that he has an Echoing Orb in his collection. He is staying at the Theramore Inn in Dustwallow Marsh. Travel quickly, retrieve the orb, and speak to no one of this. We are sending you in alone to avoid drawing the attention of our enemies. \n\nBe safe, and go with the light.", sourceObjective = "Travel to Theramore and find the mysterious merchant.", completion = "Ah, you made it! Katherine sent me to assist you in your mission. We must hurry though, our quarry has escaped!", sourceObjectiveStatus = "unverified-source-field" }
quests[81765] = { id = 81765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elrick, Paladin of the Silver Hand", description = "The Paladin standing before you is not known to you. Speak with him to determine what he knows of the merchant and the current situation.", sourceObjective = "Speak with Elrick to learn more.", completion = "Thank the light for you, {class}! I was so afraid. I thought those thugs were going to kill us!", sourceObjectiveStatus = "unverified-source-field" }
quests[81766] = { id = 81766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloody Missive", description = "You find a missive on the body of the \"paladin\". It is covered in blood and difficult to read, but you can make out the message on the parchment. You should study it and then return to Katherine for further instructions.", sourceObjective = "Bring the missive to Katherine the Pure at the Cathedral of Light in Stormwind.", progress = "So it was a trap... this is most troubling.", completion = "It's a blessing that you are safe, {name}.  I am hoping that wherever Aeonas went, he does not fall into similar danger. He is resourceful so I have to trust that he will be okay. If I hear anything from him, I will contact you immediately. Thank you, {name}.\n\nOh and one last thing. He entrusted this to me to pass onto you whenever you returned. Use it well and go with the light.", sourceObjectiveStatus = "unverified-source-field" }
quests[81768] = { id = 81768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Mission I: Defeat Satyrs", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion in Satyrnaar. Defeat satyrs there and return to me.", sourceObjective = "Defeat 10 Dreamfire Betrayers and 10 Dreamfire Hellcallers in the Ashenvale Nightmare Incursion in Satyrnaar and return to Field Captain Hannalah.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81769] = { id = 81769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Mission II: Defeat Treants", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion at the Warsong Lumber Camp. Defeat treants there and return to me.", sourceObjective = "Defeat 7 Vengeful Ancients in the Ashenvale Nightmare Incursion at the Warsong Lumber Camp and return to Field Captain Hannalah.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81770] = { id = 81770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale Mission III: Defeat Dragonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Bough Shadow, and journey to the Nightmare Incursion in Forest Song. Defeat dragonkin there and return to me.", sourceObjective = "Defeat 3 Wyrmkin Nightstalkers and 10 Terror Whelps in the Ashenvale Nightmare Incursion in Forest Song and return to Field Captain Hannalah.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
