quests[81786] = { id = 81786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission I: Defeat Moonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Skulk Rock. Defeat moonkin there and return to me.", sourceObjective = "Defeat 20 Fallen Moonkin in the Hinterlands Nightmare Incursion at Skulk Rock and return to Field Captain Korlian.", progress = "You've dealt with the moonkin?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81787] = { id = 81787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission II: Defeat Giant Turtles", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Shaol'watha. Defeat giant turtles there and return to me.", sourceObjective = "Defeat 20 Dreamwater Visejaw in the Hinterlands Nightmare Incursion at Shaol'watha and return to Field Captain Korlian.", progress = "You've dealt with the turtles?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81788] = { id = 81788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission III: Defeat Dragonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Agol'watha. Defeat dragonkin there and return to me.", sourceObjective = "Defeat 10 Wrath Whelps and 3 Wyrmkin Starhunters in the Hinterlands Nightmare Incursion at Agol'watha and return to Field Captain Korlian.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81789] = { id = 81789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission IV: Dragon Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Agol'wath. Retrieve an intelligence report from Dreamwarden Laninar there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Laninar in the Hinterlands Nightmare Incursion at the archway in Agol'watha and return to Field Captain Korlian.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81790] = { id = 81790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materials of Significance", description = "Each of the Echoing Orbs is attuned to a different aspect of its master and the method you used in Ashenvale to destroy the Althalaxx Orb will not be effective on the orb we possess. I know of a ritual that may be able to destabilize the orb and allow us to destroy it, but it requires components with specific magical significance. We already possess some of the required materials, but you'll need to retrieve the rest. Take this, it should help you in your search.", sourceObjective = "Locate the materials listed in Gregory's Note and return them to Gregory at the source of Bloodvenom Falls in Felwood.", progress = "It must have been quite the adventure to obtain these items. Well done.", completion = "Now that we have the materials, I must prepare the ritual. For now, consult with Aeonas. He wishes to speak with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[81801] = { id = 81801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Arena", description = "I am an orc of my word. You have avenged me, and I will return your favor in kind. Go to Gadgetzan and tell Fizbuz he has his champion back. \n\nI hope to see you in the ring.", sourceObjective = "Return to Fizbuz Mithril in Gadgetzan, Tanaris.", completion = "Spectacular! Everyone'll be going nuts when they hear ol' Kajind's back in town.  \n\nAnd did you say you killed a dragon for the guy!? Sounds like you'll be quite the draw yourself.\n\nI can feel it now, {name}. We're about to have a rumble for the ages in here!", sourceObjectiveStatus = "unverified-source-field" }
quests[81817] = { id = 81817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission V: Turtle Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Shaol'wath. Retrieve an intelligence report from Dreamwarden Sanathel there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Sanathel in the Hinterlands Nightmare Incursion behind the drum in Shaol'watha and return to Field Captain Korlian.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
