quests[81851] = { id = 81851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission XVII: Rescue Serlina Starbright", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Shol'watha. Find the sleeping Druid of the Claw Serlina Starbright there and escort her to safety. Then return to me.", sourceObjective = "Rescue Serlina Starbright from the Hinterlands Nightmare Incursion at the troll fortification nearest Shol'watha and return to Field Captain Korlian.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81852] = { id = 81852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlands Mission XVIII: Rescue Veanna Cloudsleeper", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Seradane, and journey to the Nightmare Incursion at Skulk Rock. Find the sleeping Druid of the Claw Veanna Cloudsleeper there and escort her to safety. Then return to me.", sourceObjective = "Rescue Veanna Cloudsleeper from the Hinterlands Nightmare Incursion in the hammock above Skulk Rock and return to Field Captain Korlian.", progress = "You rescued Veanna?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81855] = { id = 81855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission I: Defeat Children of Cenarius", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Twin Colossals. Defeat maddened sons and daughters of Cenarius there and return to me.", sourceObjective = "Defeat 10 Lost Daughters and 10 Vengeful Sons in the Feralas Nightmare Incursion at the Twin Colossals and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81856] = { id = 81856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission II: Defeat Harpies", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Ruins of Ravenwind. Defeat harpies there and return to me.", sourceObjective = "Defeat 10 Dreamspring Roguefeathers and 10 Dreamspring Stormcallers in the Feralas Nightmare Incursion at the Ruins of Ravenwind and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81857] = { id = 81857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission III: Defeat Dragonkin", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at Oneiros. Defeat dragonkin there and return to me.", sourceObjective = "Defeat 10 Frenzied Whelps and 3 Wyrmkin Berserkers in the Feralas Nightmare Incursion at Oneiros and return to Field Captain Arunnel.", progress = "You've dealt with the dragonkin?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81858] = { id = 81858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission IV: Dragon Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at Oneiros. Retrieve an intelligence report from Dreamwarden Sheldryn there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Sheldryn in the Feralas Nightmare Incursion at the southernmost ruins in Oneiros and return to Field Captain Arunnel.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81859] = { id = 81859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission V: Cenarion Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Twin Colossals. Retrieve an intelligence report from Dreamwarden Gorlas there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Gorlas in the Feralas Nightmare Incursion near the waterfall at the Twin Colossals and return to Field Captain Arunnel.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81860] = { id = 81860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission VI: Harpy Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Ruins of Ravenwind. Retrieve an intelligence report from Dreamwarden Anadelle there and return to me.", sourceObjective = "Gather intelligence from Dreamwarden Anadelle in the Feralas Nightmare Incursion at the broken gazebo in the Ruins of Ravenwind and return to Field Captain Arunnel.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
