quests[81865] = { id = 81865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission X: Moonroot", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough and collect Moonroot from within the Nightmare Incursions. We can harness its magic to reverse the damage. You will need the assistance of an herbalist.", sourceObjective = "Gather 10 Moonroot in the Feralas Nightmare Incursions and return to Field Captain Arunnel.", progress = "You have the Moonroot?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
