quests[81871] = { id = 81871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission XV: Defeat Slirena", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Ruins of Ravenwind. Defeat the harpy \"queen\" Slirena there and return to me.", sourceObjective = "Defeat Slirena in the Feralas Nightmare Incursion near the ziggurat in the Ruins of Ravenwind and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81872] = { id = 81872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission XVI: Rescue Mellias Earthtender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at Oneiros. Find the sleeping Druid of the Claw Mellias Earthtender there and escort him to safety. Then return to me.", sourceObjective = "Rescue Mellias Earthtender from the Feralas Nightmare Incursion at the stairs by Jademir Lake in Oneiros and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81873] = { id = 81873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission XVII: Rescue Nerene Brooksinger", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Twin Colossals. Find the sleeping Druid of the Claw Nerene Brooksinger there and escort her to safety. Then return to me.", sourceObjective = "Rescue Nerene Brooksinger from the Feralas Nightmare Incursion at the campfire at the Twin Colossals and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81874] = { id = 81874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas Mission XVIII: Rescue Jamniss Treemender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in Dream Bough, and journey to the Nightmare Incursion at the Ruins of Ravenwind. Find the sleeping Druid of the Claw Jamnice Treemender there and escort her to safety. Then return to me.", sourceObjective = "Rescue Jamnice Treemender from the Feralas Nightmare Incursion at the northern edge of the Ruins of Ravenwind and return to Field Captain Arunnel.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?", sourceObjectiveStatus = "unverified-source-field" }
quests[81877] = { id = 81877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night", description = "Everything's set for the grand re-opening of the Gadgetzan Arena!\n\nThe rules are simple: you'll have three fights, ending with the champ. You'll get a short break between fights, but you can't leave the arena at any point. If you do, you forfeit.\n\nWhen you're ready, the fight's on!", sourceObjective = "Claim victory in the Gadgetzan Arena.", progress = "How are ya faring, {name}? Don't tell me you've had enough!", completion = "You really put on a show out there. I was on the edge of my seat, I tell ya! The profits weren't too shabby either.\n\nAs champ, you'll get a cut of the coin, plus a little something extra just for making all this possible. To the victor goes the spoils, as they say.", sourceObjectiveStatus = "unverified-source-field" }
quests[81885] = { id = 81885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual", description = "I wanted to thank you for your efforts, {name}. Without you, I'd likely be dead and the servants of the legion would still have possession of this dangerous artifact. I know its difficult to trust an agent of the Lich King, but it is my hope that after this is over we can sway my friend back to the light. It's clear that the man I cared for is still in there. He may only need a nudge.\n\nCome now, we are needed by Gregory to help him complete the ritual. Let us speak again when it's done.", sourceObjective = "Speak with Gregory to begin the ritual.", progress = "<Aeonas stares blankly off the cliff edge in obvious shock at what just transpired>", completion = "I have no words, {name}.  Seeing Gregory again filled me with a dangerous kind of hope. His nature was laid bare from the moment we reconnected and there were plenty of signs pointing towards this end. I was blind to them.\n\nPlease, take this accursed orb and leave me. I have much to contemplate.", sourceObjectiveStatus = "unverified-source-field" }
quests[81900] = { id = 81900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Beast", description = "The carving before you depicts a two-headed beast emerging from the Dark Portal. Fel-fire spews forth from its mouths. A plaque beneath the image reads: \"Calefactus the Unleashed\". \n\nIntuition tells you the Twilight cultists may have plans to harness this creature's destructive power for their own aims.\n\nYou reason that the next step in your hunt is towards the Blasted Lands. Someone there may know more of this hellish beast.", sourceObjective = "Find an expert on the beasts of the Blasted Lands.", completion = "Tell me more of this beast, {race}. Our interests may be aligned.", sourceObjectiveStatus = "unverified-source-field" }
quests[81917] = { id = 81917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chains That Bind", description = "I have seen this creature you call \"Calefactus\" many times in my field studies. By all accounts, it appears to be an nigh-invulnerable core hound made from Fel energies.\n\nHowever, if what you say is true, and the Twilight's Hammer were planning to enslave it, then there may be a way to subdue the beast.\n\nThe Shadowsworn, to the south-east, are known to perform dark rituals, including the enslavement of fel creatures. Perhaps members of their order carry a clue to weakening Calefactus?", sourceObjective = "Bring 5 infernal chain links to Bloodmage Lynnore in the Blasted Lands", progress = "Have you found a tool to weaken Calefactus, {race}?", completion = "Interesting... yes, I can work with this.", sourceObjectiveStatus = "unverified-source-field" }
quests[81919] = { id = 81919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brought to Heel", description = "I have fashioned a tool from the chain links you found. Those of your vocation might call it a \"lasso\" of sorts. \n \nThe energy within this chain is best suited for binding demons, but seeing as Calefactus may be from beyond the dark portal, I suspect it will work on him as well.\n\nIf you take him down bring me a sample of his fel lifeblood. Such an anomalous being warrants further study.\n\nCalefactus' current location among these wastes is unknown, but I trust you'll track him down, {class}.", sourceObjective = "Bring the fel lifeblood of Calefactus the Unleashed to Bloodmage Lynnore in the Blasted Lands", progress = "Find that core hound quickly, {name}. Before the Twilight's Hammer finds him first.", completion = "Such an exquisite sample! Who knows what mysteries lie in the essence of a beast from beyond the portal?\n\nAs thanks, you may keep the lasso. I doubt I'll ever have use for such a thing, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[81924] = { id = 81924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom of the Guardians", description = "Whatever Kaldorei knowledge you seek will not be found among these ruins, {class}. Not anymore.\n\nHowever, while the physical lies in ruin, the spiritual remains.\n\nSeek the guardian spirits of Azshara, the Hinterlands, and Feralas. You will know them by their shrines. Prove yourself to them, and heed their words. Their wisdom will be passed on to you, so that it will not be lost to time as so much was here.", sourceObjective = "Prove yourself to the guardian spirits of Feralas, Azshara, and the Hinterlands, then return to Tyrisius in Feralas.", progress = "Have the spirits imparted their wisdom unto you?", completion = "You have proven a dedicated pupil, {name}. The work of preserving ancient knowledge is often arduous, but you have taken on the duty admirably.\n\nThere are many more mysteries in this world for you to uncover. I hope these tools will aid you in that journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[81944] = { id = 81944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Newly Discovered Purpose...", sourceObjective = "I... cannot explain this, {race},  but I think I have something you need. I came to this land to seek knowledge, and that search led me up the mountain over yonder to a giant stone of light, fallen from the sky. In my contemplation at the stone, An'she gifted me with a great many things. One was a sense of new purpose. Another of which was a vision of you and me, here, having this conversation. I think I gave you this.\n\nPlease, take this totem. Use it well in service of An'she... in service of the light.", sourceObjectiveStatus = "unverified-source-field" }
quests[81947] = { id = 81947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanguine Sorcery", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
