quests[81956] = { id = 81956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conjurer's Codex", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
quests[81960] = { id = 81960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clarifying Air", description = "The illegible notes are wrapped around some sapta. It's murkier than you remember, but appears to be fused with the same magic. You feel uneasy looking at it, as if it has been tainted by some ill-gotten influence. There must be a Spirit Rock nearby, though you don't know of any holy place near here. Perhaps you can get to the bottom of this strangeness by finding it.", sourceObjective = "Find the tainted Spirit Rock and drink the Murky Air Sapta.", completion = "You give life back. You strong enough. Understand... yes... you stop corruption.\n\n\nSeek and stop corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[81967] = { id = 81967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Treasure", sourceObjective = "Here ya go, boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[81968] = { id = 81968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Air's Call", description = "You strong enough. Understand... yes... you stop corruption.\n\n<The elemental shifts in discomfort.>\n\nElements in Feralas. Use Essence to find Shrine.\n\nTake fragment. Will help with corruption.", sourceObjective = "Collect 3 Elemental Essence from the water elementals on The Forgotten Coast across from Sardor Isle in Feralas and combine them with the Fragment of Air to summon help at the corrupted shrine there.", progress = "You found shrine. Clarify shrine.", completion = "Corruption... clarify now. Help needed. Perhaps others... yes... other elements help.", sourceObjectiveStatus = "unverified-source-field" }
quests[81974] = { id = 81974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Junk for Ziri", description = "You've found another G-7 C.O.R.E. Processor. This unit looks to be in worse shape than the last one, and is leaking a very caustic looking inky black fluid. It's probably junk at this point, but Ziri might have a use for it.", sourceObjective = "Talk with Ziri \"The Wrench\" Littlesprocket in Gnomeregan.", progress = "What's that you've got there, {name}?", completion = "Oh wow! A G-7 C.O.R.E. Processor. I don't think  I've ever actually seen one in person before. You should probably just throw that away. I've heard they are really dangerous.", sourceObjectiveStatus = "unverified-source-field" }
quests[81975] = { id = 81975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troubling Exchange", description = "Wait, what? Did you hit your head? Why would I ask you to bring one of these things to help fix that bucket of bolts? All that the Salvagematic needed was a few cartridge fuses, some mithril struts, and bits of enchanting essence. If I were to put a full-power G-7 Unit into that thing... well I don't know what would happen. Nothing good, that's for sure. Explosions, fire, interdimensional monsters. A real horror show most likely.", sourceObjective = "Talk to Ziri.", completion = "Imagine, thinking I'd try to put a G-7 unit into a Salvagematic! I don't have a death wish, pal.\n\n<Ziri chuckles to herself and returns to her work>", sourceObjectiveStatus = "unverified-source-field" }
quests[81986] = { id = 81986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Nightmare", description = "Now that you have Ziri's gadget, you should have everything you need to take on the Nightmare Amalgamation. Gather as many allies as you can and head back into the Nightmare by way of the portal Bough Shadow in Ashenvale. Find and destroy the Nightmare Amalgamation within its lair. \n\nOh, and one more thing... the beast is in possession of a specific item that is of great interest to me. Bring me whatever you find on its corpse and you'll be well rewarded.", sourceObjective = "Destroy the Nightmare Amalgamation and bring the Shadowy Figure any loot you find.", progress = "How goes the hunt?", completion = "Fantastic work, {name}. Now for your reward!\n\nYou see, all I wanted is a little teeny fragment of a dream hiding within this mantle, but the husk is a treasure all on its own, and that part is yours. I think you'll find that it has certain unique properties, and if you have the proper skills for it, speak with me again and I'm sure I can help you figure out just the right way to use it.", sourceObjectiveStatus = "unverified-source-field" }
quests[81987] = { id = 81987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Solutions", description = "Hey you, come here, let me take a look at you. Yeah I thought so, I can recognize a follower of the Goblin arts from a mile away. Soot stains on the knuckles, we all got it. Listen, I need some help.\n\nI've been tasked with consulting for my fellow Goblins to give them an edge out here. But these Gnomes also brought in an expert and are slowly starting to pull ahead. I got some ideas, but in the meantime lets say you bring me some Goblin Land Mines! You can make those yeah?", sourceObjective = "Bring 5 Goblin Land Mines to Maximillian \"The Greaser\" in the Shimmering Flat", progress = "Like mamma always said, \"If you can't win a fair fight, don't fight a fair fight.\" So we are going to solve this problem like my ancestors did. Covering the place with highly sensitive explosive devices!", completion = "To think these were used in the defense of Mount Hyjal against the Burning Legion. This feels like an equally good use case.", sourceObjectiveStatus = "unverified-source-field" }
quests[82001] = { id = 82001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Require Gnomish Problems", description = "Ok bad news. This Gnomish consultant they got is one step ahead of me. Turns out their racer isn't even going to be on the ground! \n\nThey are lining the racetrack with this thing called \"magnets,\" and they are going to glide just above the ground, which means no explosion! If they won't step on the mine, then we just go to bring the mine to them!\n\nI think if we have an electrical charge big enough, it should fix our issue. Go to Southwest Un'goro and bring me a Thunderstomp Stegodon horn!", sourceObjective = "Bring the Horn of a Thunderstomp Stegodon to Maximillian \"The Greaser\".", progress = "I wont go into details on how magnets work, because frankly, I don't think anybody knows.", completion = "Yeah this should do it! The perfect natural conduit we need! Shavings from this will act as a perfect trigger for the mines to go off.", sourceObjectiveStatus = "unverified-source-field" }
quests[82002] = { id = 82002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whats Red and Smells like Paint?", description = "These new Land Mines work like a charm, but we can't just be playing saboteur. We're gonna need a few upgrades to our own rides so they don't call foul play. \n\nSo we need to do the most obvious upgrade there is, a sweet paint job. And you don't even got to ask what color we are using! Hotrod red baby! The fastest color there is!\n\nWho know who's got the perfect red tint? Those Scarlet Crusade jabronis. Why don't you go sneak into Hearthglen and find me some of that nice scarlet dye.", sourceObjective = "Head to Hearthglen and find a Box of Scarlet Dye.", progress = "Its got to be the Scarlet Crusade red. Not blood red, not fireball red, not demon Orc red. Scarlet Crusade Red or bust baby!", completion = "The tasteful hue of it, the perfect gradient of red. Not even a hint of pink or orange. Just pure red goodness. Oh yeah I can feel us going faster already pal.", sourceObjectiveStatus = "unverified-source-field" }
quests[82003] = { id = 82003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory Lap For the Goblins!", description = "Ha! I did it! uh, I mean...we did it!\n\nThat amateur Gnome consultant over there is throwing in the towel! He's paying us off to skip town! Why don't you do the honors eh? You earned it kid.", sourceObjective = "Talk to Fizzbizz Coppercoil about getting a pay out.", completion = "I have a proposal that I believe will be in both of our interests.", sourceObjectiveStatus = "unverified-source-field" }
quests[82004] = { id = 82004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hush Money", description = "I can't afford the reputation loss or the financial loss you and your goblin friend are causing me. So here's the deal, I'm gonna give you inside information on how Gnomish Engineer's get stuff done. In exchange, make yourself scarce! I don't want to see you around here anymore!", sourceObjective = "Accept the Bribe from Fizzbizz Coppercoil", completion = "This is all you're getting right now! Come back a week from now and I'll have more for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[82008] = { id = 82008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomish Solutions", description = "Greetings my esteemed colleague! I can tell you are an intellectual of the highest caliber! I have need of someone of your skill set. First things first! Explosions seem to be happening all along the race track! A tad suspect wouldn't you say? Our drivers safety is our top priority. Bring me a couple of Gnomish Harm Prevention Belts! Hopefully this will solve our short term problem.", sourceObjective = "Bring Fizzbizz Coppercoil 2 Gnomish Harm Prevention Belts", progress = "Do you got the Belts? A race is about to happen and we need it STAT!", completion = "Very good! Hopefully our racer will get across the finish line in one piece. Now to move onto bigger problems.", sourceObjectiveStatus = "unverified-source-field" }
quests[82009] = { id = 82009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Require Goblin Problems", description = "Can you hear the explosions on the racetrack? No seriously, can you? Most of my hearing is gone. Anyways...\n\nMagnets! By carefully placing magnets all along the racetrack and adding the reverse polarity to the bottom of our vehicle, we shall simply float above the mines! Take that Goblins! \n\nThe last piece of the puzzle, we need something that can hold an electrical charge to manage the complicated electrical paneling. \n\nHead to Southwest Un'goro and bring me a Thunderstomp Stegodon Horn!", sourceObjective = "Bring Fizzbizz Coppercoil a Thunderstomp Stegodon Horn", progress = "The Thunderstomp Stegodon Horn is the perfect organic compound to manage the electrical fields needed to make these magnets work. Or I hope so at least, I'm not exactly sure how they work.", completion = "This will do nicely! Its still crackling with energy! If I had any hair left it would shooting in all directions!", sourceObjectiveStatus = "unverified-source-field" }
quests[82010] = { id = 82010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watering Down the Competition", description = "The time for defense is over! We won't win unless we sabotage the competition! Their fuel! Lets see. Firebloom and Rum? THIS IS WHAT GNOMISH INGENUITY IS LOSING TO? STEEPED ALCOHOL? \n\nWe need to find a way to sabotage the enemy fuel without them noticing. There is a flower of incredible red color, the compounds of the petals are unstable when the smallest amount of heat is applied. \n\nThe Scarlet Crusade uses this flower in their dyes. Go to Hearthglen and find me some.", sourceObjective = "Go to Hearthglen and find a Box of Scarlet Dye.", progress = "The Scarlet Crusade are the only ones who know of the flowers whereabouts! The compounds are strong enough that it should be concentrated enough in their dyes.", completion = "You found it! Yes, simply slipping this into the enemies gas tank should cause quite the spectacle! An explosion? No worse! They will be operating at only 76% capacity! And they won't even know it!", sourceObjectiveStatus = "unverified-source-field" }
quests[82011] = { id = 82011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory Lap for the Gnomes!", description = "We did it friend! The Goblins are throwing in the towel. In fact, the consultant the Goblins hired wants to talk to you personally! Try not to flaunt too hard now, wouldn't want them to pop a sapper!", sourceObjective = "Talk to Maximillian \"The Greaser\"", completion = "I'm a big enough to know when I'm beat. Or at least when its not worth fighting no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[82013] = { id = 82013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hush Money", description = "Let me tell you how this is gonna go. I can't afford you being around no more's so here's what we are gonna do. You are gonna leave right now. However in exchange for your generously timed excursion out of here, once a week you can come back.\n\nWhen you do, you might swing by here and see a little somethin' somethin' on the ground that you might be so inclined to pick up. And I would be so grateful for this act of service I couldn't help but feel inclined to reward you in some way.", sourceObjective = "Accept the bribe from Maximillian \"The Greaser\"", completion = "See you next week bozo.", sourceObjectiveStatus = "unverified-source-field" }
quests[82016] = { id = 82016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'ai Potent Potables", progress = "I offer quite a deal for you mon! Bring me mojo found only from de Atal'ai people, and I make you a proposition: power beyond your wildest imagination. Be warned, mon, this power can only be used de swamps it is found from. Dey say de Atal'ai practice forbidden hexcraft, and I might know a bit about 'em. \n\nSound good? Do you want to make a trade?", completion = "Ey, you won't regret this trade, mon!" }
quests[82017] = { id = 82017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Amalagamation of Nightmares", description = "The dread aura you experienced emanates not from a place, but from a creature. A particularly deadly creature of darkness, a twisted shadow reflection of the worst aspects of our world, coalesced into an amalgamation of pure nightmare. I can't explain how I know this but I... dreamt of it. Or rather, it was shown to me. It's difficult to explain.  Please, go to Moonglade and speak with the druid Loganaar. There may still be time to stop it before it gets even more powerful.", sourceObjective = "Seek out Loganaar in Moonglade", progress = "Yes, {class}?", completion = "This is most dire news. If it is as Hannalah said, the current crisis in the dream is about to get much worse.", sourceObjectiveStatus = "unverified-source-field" }
